var connected = false;
var onLineDeviceList = [];
var selectedDevice = "";
var selectedDeviceName = "";
var uploadData = null;

function uploadChatFile(c, b, d, a) {
    let ajax = new XMLHttpRequest();
    ajax.open("POST", "/chatUploadFile?address=" + b, true);
    ajax.setRequestHeader("token", localStorage.getItem("token"));
    ajax.upload.addEventListener("progress", function (e) {
    }, false);
    ajax.send(c);
    ajax.onreadystatechange = function () {
        if (ajax.readyState === 4) {
            if (ajax.status >= 200 && ajax.status < 300 || ajax.status === 304) {
                d(ajax.responseText)
            } else {
                if (ajax.status >= 302) {
                    window.location.href = ajax.getResponseHeader("Location")
                } else {
                    if (ajax.status === 500) {
                        a(ajax.responseText)
                    } else {
                        a("上传文件失败")
                    }
                }
            }
        }
    }
}

$(function () {
    let selector = document.querySelector(".chat_content");
    selector.addEventListener("dragenter", function () {
        $("#chatUploadModal").modal("show");
        uploadData = null
    }, false);
    let chatUploadModal = document.querySelector("#chatUploadModal");
    chatUploadModal.addEventListener("dragover", function (a) {
        a.preventDefault()
    }, false);
    chatUploadModal.addEventListener("dragenter", function () {
        $("#chatUploadModal").modal("show");
        uploadData = null
    }, false);
    chatUploadModal.addEventListener("dragleave", function () {
        $("#chatUploadModal").modal("hide")
    }, false);
    chatUploadModal.addEventListener("drop", function (b) {
        b.preventDefault();
        $("#chatUploadModal").modal("hide");
        uploadData = new FormData();
        Array.from(b.dataTransfer.files).forEach(function (c) {
            uploadData.append("file", c)
        });
        var a = $(".select_send_device");
        a.empty();
        a.append("<tr onclick='startSendFile(null)' class=\"select_send_device_item\"><td>本机设备</td><td></td></tr>\n");
        for (let i = 0; i < onLineDeviceList.length; i++) {
            a.append("<tr onclick='startSendFile(\"" + onLineDeviceList[i].address + '")\' class="select_send_device_item"><td>' + onLineDeviceList[i].devName + "</td><td>" + onLineDeviceList[i].devIP + "</td></tr>\n")
        }
        $("#devSelectDialog").modal("show")
    }, false);
    $(".chat_context_edit").keydown(function (c) {
        if (c.keyCode === 13 && c.shiftKey) {
            c.preventDefault();
            var b = this.selectionStart;
            var d = $(this).val().substring(0, b);
            var a = $(this).val().substring(b);
            $(this).val(d + "\r\n" + a);
            this.setSelectionRange(b + 1, b + 1);
            $(this).scrollTop($(this)[0].scrollHeight)
        } else {
            if (c.keyCode === 13 && c.ctrlKey) {
                sendMessage(true)
            } else {
                if (c.keyCode === 13) {
                    c.preventDefault();
                    sendMessage(false)
                }
            }
        }
    })
});

function startSendFile(a) {
    $("#devSelectDialog").modal("hide");
    if (a == null || a.length <= 0) {
        uploadFile(uploadData, function (b) {
            lightyear.notify(b, "success", 1000);
            uploadData = null
        }, function (b) {
            lightyear.notify(b, "danger", 1000);
            uploadData = null
        });
        return
    }
    uploadChatFile(uploadData, a, function (b) {
        lightyear.notify(b, "success", 1000);
        uploadData = null
    }, function (b) {
        lightyear.notify(b, "danger", 1000);
        uploadData = null
    })
}

function addMessage(c) {
    var j;
    if (c.isLeft) {
        var h;
        if (c.devType === 0) {
            h = $('<div class="chat_profile_photo_left ic_phone"></div>')
        } else {
            h = $('<div class="chat_profile_photo_left ic_win"></div>')
        }
        var f = $('<div class="chat_item_content_left"/>');
        var a = $('<div class="chat_left_nick clearfix">' + c.devName + "</div>");
        var d;
        if (c.messageType === 0) {
            var g = c.message.replace(/\n/g, "<br>");
            d = $('<div class="chat_left_content"></div>').html(g)
        } else {
            if (c.messageType === 1) {
                d = $('<img  src="/file/' + c.message + "?path=" + c.filePath + "&token=" + localStorage.getItem("token") + '" class="chat_left_content_img"  onclick="openFile(\'' + c.message + "','" + c.filePath + "')\">")
            } else {
                if (c.messageType === 2) {
                    d = $(' <div class="chat_left_file_content" onclick="openFile(\'' + c.message + "','" + c.filePath + '\')"><div class="file_icon"></div> <div class="file_info_content"><div class="file_info_name">' + c.message + '</div><div class="file_info_size">' + c.fileSize + "</div> </div> </div>")
                }
            }
        }
        f.append(a);
        f.append(d);
        j = $('<div class="chat_left"></div>');
        j.append(h);
        j.append(f)
    } else {
        var h;
        if (c.devType === 0) {
            h = $('<div class="chat_profile_photo_right ic_phone"></div>')
        } else {
            h = $('<div class="chat_profile_photo_right ic_win"></div>')
        }
        var f = $('<div class="chat_item_content_right"/>');
        var a = $('<div class="chat_right_nick clearfix">' + c.devName + "</div>");
        var d;
        if (c.messageType === 0) {
            var g = c.message.replace(/\n/g, "<br>");
            d = $('<div class="chat_right_content"></div>').html(g)
        } else {
            if (c.messageType === 1) {
                d = $('<img src="/file/' + c.message + "?path=" + c.filePath + "&token=" + localStorage.getItem("token") + '" class="chat_right_content_img" onclick="openFile(\'' + c.message + "','" + c.filePath + "')\">")
            } else {
                if (c.messageType === 2) {
                    d = $(' <div class="chat_right_file_content" onclick="openFile(\'' + c.message + "','" + c.filePath + '\')"><div class="' + (c.isFile ? "file_icon" : "dir_file_icon") + '"></div> <div class="file_info_content"><div class="file_info_name">' + c.message + '</div><div class="file_info_size">' + c.fileSize + "</div> </div> </div>")
                }
            }
        }
        f.append(a);
        f.append(d);
        j = $('<div class="chat_right"></div>');
        j.append(h);
        j.append(f)
    }
    var b = $(".chat_content");
    b.append(j);
    var e = document.getElementById("chat_content");
    e.scroll({top: e.scrollHeight, behavior: "smooth"})
}

var ws = null;

function initWS() {
    ws = new WebSocket("ws://" + window.location.host + "/wss?token=" + localStorage.getItem("token"));
    ws.onopen = function () {
        connected = true
    };
    ws.onmessage = function (a) {
        var b = JSON.parse(a.data);
        if (b.cmd === SEND_MSSAGE) {
            var d = {
                isLeft: b.isLeft,
                devName: b.devName,
                devType: b.devType,
                message: b.message,
                messageType: b.messageType,
                filePath: b.filePath,
                fileSize: b.fileSize
            };
            addMessage(d)
        } else {
            if (b.cmd === SYNC_DEVICE_LIST) {
                onLineDeviceList = b.data;
                var c = $(".device_selector");
                c.empty();
                c.append("<option value=''>所有设备</option>");
                for (let i = 0; i < onLineDeviceList.length; i++) {
                    if (onLineDeviceList[i].address == selectedDevice) {
                        c.append("<option selected='selected' value='" + onLineDeviceList[i].address + "'>" + onLineDeviceList[i].devName + "</option>")
                    } else {
                        c.append("<option value='" + onLineDeviceList[i].address + "'>" + onLineDeviceList[i].devName + "</option>")
                    }
                }
            } else {
                if (b.cmd === CHANGE_THEME) {
                    applyTheme(b.theme);
                    lightyear.notify("主题已切换为：" + getThemeName(b.theme), "success", 1500)
                } else {
                    if (b.cmd === DRAW_EVENT) {
                        handleDrawEvent(b)
                    }
                }
            }
        }
    };
    ws.onclose = function (a) {
        connected = false;
        lightyear.notify("与客户端连接断开！", "danger", 1000);
        $("#notConnectedModal").modal({backdrop: "static", show: true})
    };
    ws.onerror = function (a) {
        connected = false;
        lightyear.notify("连接客户端出现错误！", "danger", 1000);
        $("#notConnectedModal").modal({backdrop: "static", show: true})
    }
}

function sendMessage(e) {
    if (!connected) {
        lightyear.notify("未连接客户端，请启动LANShare后刷新页面！", "danger", 1000);
        return
    }
    var b = $(".chat_context_edit");
    var c = b.val();
    if (c == null || c.length === 0) {
        lightyear.notify("输入不能为空", "danger", 1000);
        return
    }
    var a = "所有设备";
    if (selectedDeviceName != null && selectedDeviceName.length > 0) {
        a = selectedDeviceName
    }
    var d = {
        cmd: SEND_MSSAGE,
        isLeft: false,
        devName: a + " ← 我",
        devType: 0,
        message: c,
        messageType: 0,
        selectedDevice: selectedDevice,
        isClip: e
    };
    addMessage(d);
    ws.send(JSON.stringify(d));
    b.val("");
    b[0].style.height = "40px"
}

var pressTimer;
$(".send_massage").on("mousedown", function () {
    event.preventDefault();
    pressTimer = setTimeout(function () {
        sendMessage(true);
        clearTimeout(pressTimer);
        pressTimer = null
    }, 500)
}).on("mouseup", function () {
    if (pressTimer != null) {
        clearTimeout(pressTimer);
        sendMessage(false)
    }
});
$(".device_selector").on("change", function () {
    selectedDevice = $(".device_selector").val();
    selectedDeviceName = $(".device_selector option:selected").text()
});
var btn = document.getElementById("send_massage");
btn.onmousedown = function (a) {
    a.preventDefault()
};

// ==================== 远程绘图 Canvas 逻辑（双向） ====================
var drawCanvas = null;
var drawCtx = null;
var drawInitialized = false;
var webDrawColor = "#ff0000";
var webDrawStrokeWidth = 3;
var webIsDrawing = false;

function initDrawCanvas() {
    if (drawInitialized) return;
    drawCanvas = document.getElementById("drawCanvas");
    if (!drawCanvas) return;
    drawCtx = drawCanvas.getContext("2d");
    resizeDrawCanvas();
    bindDrawEvents();
    drawInitialized = true;
}

function resizeDrawCanvas() {
    if (!drawCanvas) return;
    var container = drawCanvas.parentElement;
    drawCanvas.width = container.clientWidth;
    drawCanvas.height = container.clientHeight - 44;
}

function bindDrawEvents() {
    if (!drawCanvas) return;
    // 鼠标事件
    drawCanvas.addEventListener("mousedown", function(e) {
        e.preventDefault();
        webIsDrawing = true;
        var pos = getDrawPos(e);
        sendWebDraw("start", pos.nx, pos.ny);
        drawLocal("start", pos.x, pos.y, webDrawColor, webDrawStrokeWidth);
    });
    drawCanvas.addEventListener("mousemove", function(e) {
        if (!webIsDrawing) return;
        e.preventDefault();
        var pos = getDrawPos(e);
        sendWebDraw("move", pos.nx, pos.ny);
        drawLocal("move", pos.x, pos.y, webDrawColor, webDrawStrokeWidth);
    });
    drawCanvas.addEventListener("mouseup", function(e) {
        if (!webIsDrawing) return;
        e.preventDefault();
        webIsDrawing = false;
        var pos = getDrawPos(e);
        sendWebDraw("end", pos.nx, pos.ny);
        drawLocal("end", pos.x, pos.y, webDrawColor, webDrawStrokeWidth);
    });
    drawCanvas.addEventListener("mouseleave", function(e) {
        if (!webIsDrawing) return;
        webIsDrawing = false;
        var pos = getDrawPos(e);
        sendWebDraw("end", pos.nx, pos.ny);
        drawLocal("end", pos.x, pos.y, webDrawColor, webDrawStrokeWidth);
    });
    // 触摸事件
    drawCanvas.addEventListener("touchstart", function(e) {
        e.preventDefault();
        webIsDrawing = true;
        var pos = getDrawPosTouch(e);
        sendWebDraw("start", pos.nx, pos.ny);
        drawLocal("start", pos.x, pos.y, webDrawColor, webDrawStrokeWidth);
    });
    drawCanvas.addEventListener("touchmove", function(e) {
        if (!webIsDrawing) return;
        e.preventDefault();
        var pos = getDrawPosTouch(e);
        sendWebDraw("move", pos.nx, pos.ny);
        drawLocal("move", pos.x, pos.y, webDrawColor, webDrawStrokeWidth);
    });
    drawCanvas.addEventListener("touchend", function(e) {
        if (!webIsDrawing) return;
        webIsDrawing = false;
        var rect = drawCanvas.getBoundingClientRect();
        var touch = e.changedTouches[0];
        var x = touch.clientX - rect.left;
        var y = touch.clientY - rect.top;
        sendWebDraw("end", x / drawCanvas.width, y / drawCanvas.height);
        drawLocal("end", x, y, webDrawColor, webDrawStrokeWidth);
    });
    // 工具栏事件
    var colorPicker = document.getElementById("drawColorPicker");
    if (colorPicker) {
        colorPicker.addEventListener("input", function() { webDrawColor = this.value; });
    }
    var strokeRange = document.getElementById("drawStrokeRange");
    if (strokeRange) {
        strokeRange.addEventListener("input", function() { webDrawStrokeWidth = parseInt(this.value); });
    }
}

function getDrawPos(e) {
    var rect = drawCanvas.getBoundingClientRect();
    var x = e.clientX - rect.left;
    var y = e.clientY - rect.top;
    return { x: x, y: y, nx: x / drawCanvas.width, ny: y / drawCanvas.height };
}

function getDrawPosTouch(e) {
    var rect = drawCanvas.getBoundingClientRect();
    var touch = e.touches[0];
    var x = touch.clientX - rect.left;
    var y = touch.clientY - rect.top;
    return { x: x, y: y, nx: x / drawCanvas.width, ny: y / drawCanvas.height };
}

function sendWebDraw(action, nx, ny) {
    if (!ws || ws.readyState !== WebSocket.OPEN) return;
    var colorInt = hexToColorInt(webDrawColor);
    var msg = {
        cmd: DRAW_EVENT,
        action: action,
        x: nx,
        y: ny,
        color: colorInt,
        strokeWidth: webDrawStrokeWidth,
        from: "web"
    };
    ws.send(JSON.stringify(msg));
}

function hexToColorInt(hex) {
    hex = hex.replace("#", "");
    var r = parseInt(hex.substring(0, 2), 16);
    var g = parseInt(hex.substring(2, 4), 16);
    var b = parseInt(hex.substring(4, 6), 16);
    // 转为 Android signed int (AARRGGBB)
    var value = (255 << 24) | (r << 16) | (g << 8) | b;
    return value | 0; // 强制转 signed
}

function drawLocal(action, x, y, color, strokeWidth) {
    if (!drawCtx) return;
    drawCtx.lineCap = "round";
    drawCtx.lineJoin = "round";
    if (action === "start") {
        drawCtx.beginPath();
        drawCtx.moveTo(x, y);
        drawCtx.strokeStyle = color;
        drawCtx.lineWidth = strokeWidth;
    } else if (action === "move") {
        drawCtx.lineTo(x, y);
        drawCtx.stroke();
    } else if (action === "end") {
        drawCtx.lineTo(x, y);
        drawCtx.stroke();
        drawCtx.closePath();
    }
}

function handleDrawEvent(b) {
    // 防止回显：忽略来自其他网页客户端的事件
    if (b.from === "web") return;
    if (!drawInitialized) {
        initDrawCanvas();
    }
    if (!drawCtx) return;
    var action = b.action;
    var x = b.x * drawCanvas.width;
    var y = b.y * drawCanvas.height;
    var color = b.color;
    var strokeWidth = b.strokeWidth;

    var statusEl = document.getElementById("draw_status");
    if (statusEl && action === "start") {
        statusEl.textContent = "APP正在绘图...";
        statusEl.style.color = "#4CAF50";
    }

    // Android int 转 hex 颜色
    var hex = (color >>> 0).toString(16);
    hex = hex.length > 6 ? hex.slice(-6) : hex.padStart(6, "0");
    var cssColor = "#" + hex;

    drawCtx.lineCap = "round";
    drawCtx.lineJoin = "round";

    if (action === "start") {
        drawCtx.beginPath();
        drawCtx.moveTo(x, y);
        drawCtx.strokeStyle = cssColor;
        drawCtx.lineWidth = strokeWidth;
    } else if (action === "move") {
        drawCtx.lineTo(x, y);
        drawCtx.stroke();
    } else if (action === "end") {
        drawCtx.lineTo(x, y);
        drawCtx.stroke();
        drawCtx.closePath();
    } else if (action === "clear") {
        drawCtx.clearRect(0, 0, drawCanvas.width, drawCanvas.height);
        if (statusEl) {
            statusEl.textContent = "画布已清空";
            statusEl.style.color = "#999";
        }
    }
}

function clearDrawCanvas() {
    if (drawCtx && drawCanvas) {
        drawCtx.clearRect(0, 0, drawCanvas.width, drawCanvas.height);
        var statusEl = document.getElementById("draw_status");
        if (statusEl) {
            statusEl.textContent = "画布已清空";
            statusEl.style.color = "#999";
        }
    }
    // 发送清空事件到APP
    if (ws && ws.readyState === WebSocket.OPEN) {
        ws.send(JSON.stringify({ cmd: DRAW_EVENT, action: "clear", from: "web" }));
    }
}

window.addEventListener("resize", function() {
    if (drawInitialized) resizeDrawCanvas();
});